function should_inject(request, flow_store)
  local fid = 'lua'
  local count = (flow_store:get(fid, 'count') or 0) + 1
  flow_store:set(fid, 'count', count)
  return {
    inject = true,
    fault = 'error',
    status = 200,
    body = '{"engine":"lua","count":' .. count .. '}',
    headers = {['Content-Type'] = 'application/json'}
  }
end
